"""A utility function that converts a "'string'" to a "string" """
def unwrap_string(s: Any) -> object {
    s = s.replace("'", "");
    return s;
}

test_blocks:
test "t0" {
    assert (unwrap_string("'test_string'") == "test_string");;
}

test "t1" {
    assert (unwrap_string(("a" + "b" + "c")) == "abc");;
}

test "t2" {
    assert (unwrap_string("'a'") == "a");;
}

test "t3" {
    assert (unwrap_string('I am a string') == 'I am a string');;
}

